package com.bank.minnotes.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Finds the fewest notes to form an amount with unlimited supply (minimization DP).
public class MinNotesService {
    private static final Logger log = Logger.getLogger(MinNotesService.class.getName());

    public int minCoins(int[] denominations, int amount) {
        int sentinel = amount + 1;                  // larger than any real answer
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, sentinel);
        dp[0] = 0;                                  // zero needs no notes
        for (int a = 1; a <= amount; a++) {
            for (int note : denominations) {
                if (note <= a) {
                    dp[a] = Math.min(dp[a], 1 + dp[a - note]);   // one note + remainder
                }
            }
        }
        int result = dp[amount] > amount ? -1 : dp[amount];
        final int r = result;
        log.info(() -> "Fewest notes for " + amount + " = " + r);
        return result;
    }
}
