package com.bank.minnotes;

import com.bank.minnotes.service.MinNotesService;
import java.util.logging.Logger;

public class MinNotesApplication {
    private static final Logger log = Logger.getLogger(MinNotesApplication.class.getName());

    public static void main(String[] args) {
        MinNotesService service = new MinNotesService();
        int[] notes = {1, 3, 5};        // note denominations (hundreds)
        int amount = 7;
        int fewest = service.minCoins(notes, amount);
        log.info("Fewest notes to dispense " + amount + ": " + fewest);
    }
}
